package functions
FLAG :: #config(FUZZ_BRANCH, true)
when FLAG {
	value :: proc() -> int {return 1}
} else {
	value :: proc() -> int {return 2}
}
@(private)
helper :: proc() -> int {
	if true {return value()}
	else {return 0}
}
read :: proc() -> int {return helper()}

